import { computed, defineComponent, h, type PropType } from 'vue';
import { alertStyleKeys, getAlertStyleKeys } from '../lib/core';
import type { AlertVariant } from '../lib/core';
import styles from './alert.module.scss';

export const Alert = defineComponent({
	name: 'Alert',
	props: {
		variant: {
			type: String as PropType<AlertVariant>,
			default: 'default',
		},
	},
	setup(props, { slots, attrs }) {
		const styleKeys = computed(() => getAlertStyleKeys(props.variant));
		const classes = computed(() => [styles[styleKeys.value.base], styles[styleKeys.value.variant], attrs.class]);

		return () => h('div', { ...attrs, role: 'alert', 'data-slot': 'alert', 'data-variant': props.variant, class: classes.value }, slots.default?.());
	},
});

export const AlertTitle = defineComponent({
	name: 'AlertTitle',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, 'data-slot': 'alert-title', class: [styles[alertStyleKeys.title], attrs.class] }, slots.default?.());
	},
});

export const AlertDescription = defineComponent({
	name: 'AlertDescription',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, 'data-slot': 'alert-description', class: [styles[alertStyleKeys.description], attrs.class] }, slots.default?.());
	},
});

export default Alert;

@use '../../../styles/variables/colors' as *;

// Alert 根容器：网格布局，直接子 svg 图标占据首列
.alert {
	position: relative;
	display: grid;
	width: 100%;
	grid-template-columns: 0 1fr;
	align-items: start;
	gap: $spacing-1;
	border-radius: var(--tile-alert-radius, $radius);
	border: 1px solid transparent;
	padding: var(--tile-alert-padding, $spacing-3 $spacing-4);
	font-size: var(--tile-alert-font-size, $text-sm);

	// 存在直接子 SVG 图标时启用图标列
	&:has(> svg) {
		grid-template-columns: $spacing-4 1fr;
		gap: $spacing-3;
	}

	> svg {
		width: $spacing-4;
		height: $spacing-4;
		transform: translateY(2px);
		color: currentColor;
	}

	// 样式变体
	&.variantDefault {
		background-color: var(--tile-alert-background, $card);
		color: var(--tile-alert-color, $card-foreground);
		border-color: var(--tile-alert-border, $border);
	}

	&.variantDestructive {
		background-color: var(--tile-alert-error-background, $card);
		color: var(--tile-alert-error-color, $destructive);
		border-color: var(--tile-alert-error-border, color-mix(in srgb, $destructive 30%, transparent));

		.description {
			color: var(--tile-alert-error-color, $destructive-muted-foreground);
		}
	}
}

// 标题与描述统一放在第二列
.title,
.description {
	grid-column-start: 2;
}

// 标题
.title {
	min-height: $spacing-4;
	font-weight: $font-medium;
	line-height: var(--tile-alert-title-leading, $leading-tight);
	letter-spacing: var(--tile-alert-title-tracking, -0.01em);
	overflow-wrap: anywhere;
}

// 描述
.description {
	display: grid;
	justify-items: start;
	gap: $spacing-1;
	font-size: $text-sm;
	line-height: var(--tile-alert-description-leading, $leading-relaxed);
	color: var(--tile-alert-description-color, $muted-foreground);

	p {
		line-height: var(--tile-alert-description-leading, $leading-relaxed);
	}
}
